    static void EnterPlay(SeasideMainMenuPatch.HomeView v)
    {
        v.Tick(true); Proxy("Play").OnClick.Invoke(); Pump(v,160);
        Check(v.Page==SeasidePage.Play && !v.Transitioning && v.Visible);
    }
    static void Phase3Tests()
    {
        Test("phase3 starts at Home and refuses an empty transition",()=>{var t=new SeasideTransition();Check(t.Page==SeasidePage.Home&&!t.Active&&!t.Begin(SeasidePage.Home));});
        Test("phase3 begins forward once and refuses reentry",()=>{var t=new SeasideTransition();Check(t.Begin(SeasidePage.Play)&&!t.Reverse&&!t.Begin(SeasidePage.Play)&&!t.Begin(SeasidePage.Home));});
        Test("phase3 page swap is later than the fully covered frame",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(.49);Check(t.FullyCovered&&t.Page==SeasidePage.Home);t.Advance(.01);Check(t.Page==SeasidePage.Play&&t.FullyCovered);});
        Test("phase3 nominal duration is 2.6 seconds and completes only once",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);Check(!t.Advance(2.599)&&t.Active);Check(t.Advance(.001)&&!t.Active&&t.Page==SeasidePage.Play&&!t.Advance(.5));Near(t.Time,2.6);});
        Test("phase3 a stalled frame still reaches a safe completed state",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);Check(t.Advance(50)&&t.Page==SeasidePage.Play&&!t.Active);});
        Test("phase3 invalid time never corrupts the timeline",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);foreach(var dt in new[]{double.NaN,double.PositiveInfinity,-1d,0d})Check(!t.Advance(dt)&&t.Time==0&&t.Page==SeasidePage.Home);});
        foreach(double at in new[]{.46,.5,1d,1.7,2d,2.3})Test("phase3 opaque core covers the whole screen at "+at,()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(at);for(int i=0;i<=256;i++){var r=t.Span(i/256d);Check(r.Left<=0&&r.Right>=1);}Check(t.FullyCovered);});
        Test("phase3 forward crest moves from left to right",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);double old=-1;for(int i=0;i<24;i++){t.Advance(.02);var r=t.Span(.5);Check(r.Right>=old);old=r.Right;}});
        Test("phase3 edge has a curved profile instead of a rectangle",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(.2);var edges=Enumerable.Range(0,100).Select(i=>t.Span(i/99d).Right);Check(edges.Max()-edges.Min()>.04);});
        Test("phase3 reverse wave mirrors the forward wave at every row",()=>{var a=new SeasideTransition();var b=new SeasideTransition();a.Begin(SeasidePage.Play);b.Restore(SeasidePage.Play);b.Begin(SeasidePage.Home);for(int i=0;i<130;i++){a.Advance(.02);b.Advance(.02);for(int j=0;j<=8;j++){var x=a.Span(j/8d);var y=b.Span(j/8d);Near(x.Left,1-y.Right);Near(x.Right,1-y.Left);}}});
        Test("phase3 letters start at distinct positions and rotations",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(.6);Check(Enumerable.Range(0,9).Select(i=>t.Letter(i).Y).Distinct().Count()>3);Check(Enumerable.Range(0,9).Any(i=>Math.Abs(t.Letter(i).Rotation)>1));});
        Test("phase3 all letters assemble exactly at 1.7s",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(1.7);for(int i=0;i<9;i++){var x=t.Letter(i);Near(x.X,SeasideTransition.TargetX(i));Near(x.Y,.5);Near(x.Rotation,0);Near(x.Alpha,1);}});
        Test("phase3 final word holds still for 0.6 seconds",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(1.7);var poses=Enumerable.Range(0,9).Select(t.Letter).ToArray();t.Advance(.6);Check(Enumerable.Range(0,9).All(i=>t.Letter(i)==poses[i]));});
        Test("phase3 completed letters leave along with the water",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(2.45);Check(t.Letter(0).X>.8);t.Cancel();t.Restore(SeasidePage.Play);t.Begin(SeasidePage.Home);t.Advance(2.45);Check(t.Letter(0).X<0);});
        foreach(double at in new[]{.2,1d,2.4})Test("phase3 cancelling at "+at+" restores the source page",()=>{var t=new SeasideTransition();t.Begin(SeasidePage.Play);t.Advance(at);t.Cancel();Check(!t.Active&&t.Page==SeasidePage.Home&&t.Time==0);});
        Test("phase3 play layout leaves artwork and version labels intact",()=>{foreach(var id in SeasidePlayLayout.Ids){var r=SeasidePlayLayout.Rect(id);Check(r.Y>=240&&r.Y+r.Height<=910&&!r.Overlaps(SeasideMenuLayout.GameVersionBox)&&!r.Overlaps(SeasideMenuLayout.VersionBox));foreach(var other in SeasidePlayLayout.Ids.Where(x=>x!=id))Check(!r.Overlaps(SeasidePlayLayout.Rect(other)));}});
