        foreach(string id in new[]{"PlayOnline","PlayLocal"})Test("phase3 existing native action executes once: "+id,()=>{var x=Setup();EnterPlay(x.view);var original=id=="PlayOnline"?x.menu.PlayOnlineButton:x.menu.playLocalButton;Proxy(id).OnClick.Invoke();Pump(x.view,4);Check(original.OnClick.Calls==0);Pump(x.view,20);Check(original.OnClick.Calls==1&&!x.view.Visible);x.view.Dispose();});
        Test("phase3 disabled online authority button is not bypassed",()=>{var x=Setup();EnterPlay(x.view);x.menu.PlayOnlineButton.enabled=false;Proxy("PlayOnline").OnClick.Invoke();Pump(x.view);Check(x.menu.PlayOnlineButton.OnClick.Calls==0&&x.view.Visible);x.view.Dispose();});
        Test("phase3 native action exceptions restore a usable page",()=>{var x=Setup();EnterPlay(x.view);x.menu.PlayOnlineButton.OnClick.AddListener(()=>throw new Exception("synthetic"));Proxy("PlayOnline").OnClick.Invoke();Pump(x.view,25);Check(x.view.Visible&&!x.view.Transitioning);x.view.Dispose();});
        Test("phase3 native play-panel return resumes the custom page",()=>{var x=Setup();EnterPlay(x.view);Proxy("PlayOnline").OnClick.Invoke();Pump(x.view);Check(!x.view.Visible);Check(x.view.ResumeNativePlay());x.view.Tick(true);Check(x.view.Visible&&x.view.Page==SeasidePage.Play&&!Proxy("Play").gameObject.activeSelf);x.view.Dispose();});
        Test("phase3 escape uses the same press and reverse transition",()=>{var x=Setup();EnterPlay(x.view);Input.Escape=true;Pump(x.view,1);Check(!x.view.Transitioning);Pump(x.view,160);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning);x.view.Dispose();});
        Test("phase3 native reset cannot bypass back feedback or interrupt water",()=>{var x=Setup();typeof(SeasideMainMenuPatch).GetField("view",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,x.view);EnterPlay(x.view);Check(!(bool)Call("BeforeReset",x.menu));Call("Reset",x.menu);Pump(x.view,16);Check(x.view.Transitioning);Check(!(bool)Call("BeforeReset",x.menu));Call("Reset",x.menu);Pump(x.view,150);Check(x.view.Page==SeasidePage.Home&&!x.view.Transitioning);x.view.Dispose();});
        Test("phase3 a popup cancels the wave without trapping input",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,45);x.view.Hide();Check(!x.view.Transitioning&&x.menu.playButton.GetComponent<BoxCollider2D>().enabled);x.view.Tick(true);Check(x.view.Page==SeasidePage.Home&&x.view.Visible);x.view.Dispose();});
        Test("phase3 owner destruction disposes all wave letter objects",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,20);Check(Obj.Objects.Any(o=>o.name.StartsWith("WaveLetter_")));x.view.Dispose();Check(!Obj.Objects.Any(o=>o.name.StartsWith("WaveLetter_")||o.name=="SeasideWaveTransition"));});
        Test("phase3 a foreign controller state cannot leak a queued choice",()=>{var x=Setup();EnterPlay(x.view);Proxy("PlayLocal").OnClick.Invoke();Pump(x.view,3);ControllerManager.Instance.CurrentUiState=new();Pump(x.view,20);Check(x.menu.playLocalButton.OnClick.Calls==0);x.view.Dispose();});
        Test("phase3 repeated home callbacks advance water only once per frame",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,16);var t=(SeasideTransition)typeof(SeasideMainMenuPatch.HomeView).GetField("transition",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(x.view);var old=t.Time;for(int i=0;i<10;i++)x.view.Tick(true);Near(t.Time,old);x.view.Dispose();});
