        Test("phase3 play buttons reuse hover and press poses",()=>{var x=Setup();EnterPlay(x.view);Proxy("PlayBack").OnMouseOver.Invoke();Pump(x.view,15);Check(Math.Abs(Motion("PlayBack").localRotation.Z)>.01);Proxy("PlayBack").OnClick.Invoke();Pump(x.view,6);Near(Motion("PlayBack").localRotation.Z,0);Near(Motion("PlayBack").localScale.y,.95);x.view.Dispose();});
        foreach(float ratio in new[]{4f/3,16f/9,21f/9,9f/16})Test("phase3 wave spans the whole viewport at ratio "+ratio,()=>{var x=Setup();Camera.main.aspect=ratio;x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,55);var mesh=Obj.Objects.Single(o=>o.name=="SeasideWaveTransition").GetComponent<MeshFilter>().mesh;var scale=Obj.Objects.Single(o=>o.name=="ShellSeasideHome").transform.localScale.x;double h=Camera.main.orthographicSize*2/scale,w=h*ratio;Check(mesh.vertices.Length>3000&&mesh.triangles.All(i=>i>=0&&i<mesh.vertices.Length));Near(mesh.vertices.Min(v=>v.x),-w/2);Near(mesh.vertices.Max(v=>v.x),w/2);Near(mesh.vertices.Min(v=>v.y),-h/2);Near(mesh.vertices.Max(v=>v.y),h/2);x.view.Dispose();});
        Test("phase3 important errors still take precedence over the wave",()=>{var x=Setup();typeof(SeasideMainMenuPatch).GetField("view",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,x.view);x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,20);var popup=new GameObject("CriticalPopup").AddComponent<GenericPopup>();Call("GenericOpening",popup);Check(!x.view.Visible&&!x.view.Transitioning);x.view.Dispose();});
        Test("phase3 visible ErrorText cancels the wave and can recover after clearing",()=>{var x=Setup();typeof(SeasideMainMenuPatch).GetField("view",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,x.view);x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,30);ErrorText.Instance=new(){Text=new GameObject("CriticalErrorText").AddComponent<TextMeshPro>()};Call("Tick",x.menu);Check(!x.view.Visible&&!x.view.Transitioning);ErrorText.Instance.Text.enabled=false;Call("Tick",x.menu);Check(x.view.Visible&&x.view.Page==SeasidePage.Home);x.view.Dispose();});
        Test("phase3 losing controller ownership cancels the wave without taking over the new state",()=>{var x=Setup();x.view.Tick(true);Proxy("Play").OnClick.Invoke();Pump(x.view,25);var foreign=new ControllerUiElementsState();ControllerManager.Instance.CurrentUiState=foreign;Pump(x.view,1);Check(!x.view.Transitioning&&ControllerManager.Instance.CurrentUiState==foreign&&foreign.SelectableUiElements.Count==0);x.view.Dispose();});
