        Test("phase3 online return resumes after the existing logo-hiding postfix",()=>{var x=Setup();typeof(SeasideMainMenuPatch).GetField("view",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).SetValue(null,x.view);EnterPlay(x.view);Proxy("PlayOnline").OnClick.Invoke();Pump(x.view);Check(!(bool)Call("NativePlayPage",x.menu));CredentialsPatch.TOHhmLogo.gameObject.SetActive(false);Call("NativePlayPageFinished",x.menu);Check(CredentialsPatch.TOHhmLogo.gameObject.activeSelf&&x.view.Visible&&x.view.Page==SeasidePage.Play&&!x.view.Transitioning);x.view.Dispose();});
