    static void ExportTransition(string path)
    {
        var runs=new List<object>();
        foreach(bool reverse in new[]{false,true})
        {
            var t=new SeasideTransition();if(reverse)t.Restore(SeasidePage.Play);t.Begin(reverse?SeasidePage.Home:SeasidePage.Play);
            var frames=new List<object>();
            for(int i=0;i<=156;i++)
            {
                double at=i/60d;if(i>0)t.Advance(at-t.Time);
                frames.Add(new { time=at,active=t.Active,page=t.Page.ToString(),spans=Enumerable.Range(0,97).Select(j=>t.Span(j/96d)).ToArray(),letters=Enumerable.Range(0,9).Select(t.Letter).ToArray() });
            }
            runs.Add(new { reverse,frames });
        }
        File.WriteAllText(path,JsonSerializer.Serialize(new { duration=SeasideTransition.Duration,assembleEnd=SeasideTransition.AssembleEnd,holdEnd=SeasideTransition.HoldEnd,word=SeasideTransition.Word,online=SeasidePlayLayout.Online,local=SeasidePlayLayout.Local,back=SeasidePlayLayout.Back,runs }));
    }
